public class Solution {
    public int[] TopKFrequent(int[] events, int k) {
        var freq = new Dictionary<int, int>();
        foreach (int val in events) {
            freq[val] = freq.GetValueOrDefault(val) + 1;
        }
        var minHeap = new PriorityQueue<int, int>(Comparer<int>.Create((a, b) => a.CompareTo(b)));
        var heapMap = new Dictionary<int, int>();
        foreach (var (val, count) in freq) {
            minHeap.Enqueue(val, count);
            heapMap[val] = count;
            if (minHeap.Count > k) {
                int removed = minHeap.Dequeue();
                heapMap.Remove(removed);
            }
        }
        return heapMap.Keys.ToArray();
    }
}

