func topKFrequent(events []int, k int) []int {
    freq := make(map[int]int)
    for _, v := range events {
        freq[v]++
    }
    h := &minHeap{}
    heap.Init(h)
    for val, cnt := range freq {
        heap.Push(h, pair{cnt, val})
        if h.Len() > k {
            heap.Pop(h)
        }
    }
    res := make([]int, h.Len())
    for i := 0; i < len(res); i++ {
        res[i] = heap.Pop(h).(pair).val
    }
    return res
}

