def topKFrequent(events, k):
    from collections import Counter
    import heapq
    freq = Counter(events)
    heap = []
    for val, count in freq.items():
        heapq.heappush(heap, (count, val))
        if len(heap) > k:
            heapq.heappop(heap)
    return [val for _, val in heap]

